#!/usr/bin/env node
// Generated by Keel — byte budgets + split-doc integrity. Copy to .keel/doc-size.mjs.
// Usage: node .keel/doc-size.mjs [--json] [--after-archive]   check (read-only)
//        node .keel/doc-size.mjs --split <doc.md>             split one oversize doc or part (writes files)
//        node .keel/doc-size.mjs --self-test
// One VERDICT per doc, with the reason:
//   ok      within budget (or an archive: append-only history, never budgeted, never split)
//   waived  over budget, but .keel/meta.json "waivers" records why (reason + reviewed date)
//   archive move closed detail out first (keystone: then move whole sections to docs/agents/, linked)
//   split   split into docs/<name>/NN-<slug>.md behind the parent index (--split does it)
//   manual  over budget and no safe automatic fix (generated file, no headings, index too big)
// Measured once each: AGENTS.md, CLAUDE.md, root CHANGELOG/COMMANDS/RUNBOOK.md, top-level docs/*.md,
// docs/adr/README.md, every "budgets"/"waivers" key, and every part of a split doc. A SPLIT doc is a
// parent NAME.md with a "## Parts" heading AND a sibling folder name/ — a folder alone (docs/ADR.md
// beside docs/adr/) is not a split. Budget = budgets[path] ?? defaultBudget ?? 32768; an ADR index's
// budget grows 320 B per ADR file. Exit 1 only on link errors (part not linked from parent / no link
// back). Links count inline, reference-style, file-relative and repo-absolute (/docs/x.md).
import { readdirSync, readFileSync, statSync, existsSync, writeFileSync, mkdirSync, mkdtempSync } from 'fs'
import { join, dirname, basename, relative, posix } from 'path'
import { tmpdir } from 'os'

const KEYSTONE = new Set(['AGENTS.md', 'CLAUDE.md'])
const ROOT_DOCS = ['AGENTS.md', 'CLAUDE.md', 'CHANGELOG.md', 'COMMANDS.md', 'RUNBOOK.md', 'docs/adr/README.md']
const ARCHIVABLE = new Set(['docs/IMPLEMENTATION_PLAN.md', 'CHANGELOG.md', 'docs/CHANGELOG.md',
  'RUNBOOK.md', 'docs/RUNBOOK.md', 'docs/DEPLOYMENT.md'])
const ADR_ROW = 320
const kebab = f => basename(f, '.md').toLowerCase().replace(/_/g, '-')
const isArchive = (f, meta) => /ARCHIVE/i.test(basename(f)) || /^LEGACY_/i.test(basename(f)) ||
  /(^|\/)archive\//i.test(f) || (meta.archives || []).includes(f)
const isGenerated = text => /^(<!--[^\n]*)?[^\n]*\b(auto-?generated|do not edit|generated by (?!keel))/im.test(text.slice(0, 400))
const hasParts = text => /^## Parts\s*$/m.test(text)
const day = 864e5

// Every link target in a markdown file, as a repo-relative path (anchors and titles dropped).
export function linkTargets(text, from) {
  const raw = [...text.matchAll(/\]\(\s*<?([^)\s>]+)>?(?:\s+["'(][^)]*)?\)/g),
    ...text.matchAll(/^ {0,3}\[[^\]]+\]:\s*<?(\S+?)>?(?:\s+.*)?$/gm)].map(m => m[1])
  const out = new Set()
  for (let t of raw) {
    t = t.split('#')[0]
    if (!t || /^[a-z][\w+.-]*:/i.test(t)) continue
    out.add(t.startsWith('/') ? posix.normalize(t.slice(1)) : posix.join(posix.dirname(from), t))
  }
  return out
}

// Count "## " (else "### ") sections outside code fences, excluding a "## Parts" index table.
function splittable(text, isPart) {
  for (const lvl of [2, 3]) {
    const n = sections(text, lvl).slice(1).filter(s => s.title !== 'Parts').length
    if (n >= (isPart ? 2 : 1) && (n >= 2 || !isPart)) return true
  }
  return false
}

export function check(root, { afterArchive = false, now = Date.now() } = {}) {
  let meta = {}
  try { meta = JSON.parse(readFileSync(join(root, '.keel/meta.json'), 'utf8')) } catch {}
  const budgets = meta.budgets || {}
  const def = meta.defaultBudget || 32768
  // waivers {path: {reason, reviewed, max?}}; legacy budgetExceptions {path: "reason"} read as unreviewed waivers
  const waivers = { ...Object.fromEntries(Object.entries(meta.budgetExceptions || {}).map(([f, r]) =>
    [f, { reason: String(r), reviewed: null, legacy: true }])), ...(meta.waivers || {}) }
  const reviewDays = meta.waiverReviewDays || 90
  const exists = f => existsSync(join(root, f)) && statSync(join(root, f)).isFile()
  const mds = d => existsSync(join(root, d)) ? readdirSync(join(root, d)).filter(f => f.endsWith('.md')).map(f => `${d}/${f}`) : []
  const docs = [...new Set([...ROOT_DOCS, ...mds('docs'), ...Object.keys(budgets), ...Object.keys(waivers)])].filter(exists)
  const adrCount = mds('docs/adr').filter(f => /\/ADR-\d+/i.test(f)).length
  const files = [], linkErrors = [], families = [], seen = new Set()

  const judge = (f, budget, part) => {
    if (seen.has(f)) return 0
    seen.add(f)
    const text = readFileSync(join(root, f), 'utf8'), size = Buffer.byteLength(text)
    const isAdrIndex = /(^|\/)adr\/README\.md$/i.test(f)
    if (isAdrIndex && f === 'docs/adr/README.md') budget = Math.max(budget, adrCount * ADR_ROW)
    const r = { file: f, size, budget, part: part || null }
    const w = waivers[f]
    if (isArchive(f, meta)) Object.assign(r, { verdict: 'ok', reason: 'archive: append-only history, not budgeted, never split' })
    else if (size <= budget) {
      const left = budget - size
      Object.assign(r, { verdict: 'ok', reason: isAdrIndex && adrCount ? `ADR index, budget ${ADR_ROW} B × ${adrCount} ADRs` :
        left < Math.max(256, budget * 0.02) ? `tight: ${left} B left — move content out before adding` : '' })
    } else if (w && !(w.max && size > w.max)) {
      const due = !w.reviewed || now - Date.parse(w.reviewed) > reviewDays * day
      Object.assign(r, { verdict: 'waived', reason: `${w.reason}${due ? ` — review due${w.legacy ? ' (legacy budgetExceptions entry: move to "waivers" with a reviewed date)' : ''}` : ` (reviewed ${w.reviewed})`}` })
    } else if (KEYSTONE.has(f)) Object.assign(r, { verdict: 'archive', reason: 'keystone, never split: archive closed detail, then move whole sections to a linked doc under docs/ and leave a one-line pointer — do not compress wording' })
    else if (isGenerated(text)) Object.assign(r, { verdict: 'manual', reason: 'generated file: shrink its generator or add a waiver — a split would be overwritten' })
    else if (isAdrIndex) Object.assign(r, { verdict: 'manual', reason: `ADR index over ${ADR_ROW} B per ADR: shorten row titles or add a waiver — never split an index` })
    else if (ARCHIVABLE.has(f) && !afterArchive) Object.assign(r, { verdict: 'archive', reason:
      (f.endsWith('IMPLEMENTATION_PLAN.md') ? 'move done phases to PHASE_ARCHIVE; if open deferred rows dominate run /keel closeout' : 'move closed entries to its archive') + '; split only if still over after that' })
    else if (part ? splittable(text, true) : splittable(text, false))
      Object.assign(r, { verdict: 'split', reason: part ? `part of ${part}: split it further (new parts, linked both ways)` : 'split into its folder behind a slim index' })
    else Object.assign(r, { verdict: 'manual', reason: hasParts(text) && !part ? 'index only, yet over budget: shorten the Parts table or add a waiver' :
      'no "## " or "### " headings to split at (or one section only): add headings or split by hand' })
    if (ARCHIVABLE.has(f) && r.verdict === 'split') r.reason += ' (archive already done)'
    files.push(r)
    return size
  }

  for (const doc of docs) {
    const budget = budgets[doc] ?? def
    let total = judge(doc, budget)
    // keystone moves sections out to docs/agents/ (docs/claude/), never splits itself
    const folder = KEYSTONE.has(doc) ? `docs/${kebab(doc)}` : posix.join(posix.dirname(doc), kebab(doc))
    const parentText = readFileSync(join(root, doc), 'utf8')
    if (!hasParts(parentText) || !existsSync(join(root, folder)) || !statSync(join(root, folder)).isDirectory()) continue
    const parts = readdirSync(join(root, folder)).filter(f => f.endsWith('.md')).sort()
    const fromParent = linkTargets(parentText, doc)
    for (const p of parts) {
      const rel = `${folder}/${p}`
      total += judge(rel, budget, doc)
      if (!fromParent.has(rel)) linkErrors.push(`${rel}: not linked from ${doc}`)
      if (!linkTargets(readFileSync(join(root, rel), 'utf8'), rel).has(doc)) linkErrors.push(`${rel}: no link back to ${doc}`)
    }
    families.push({ parent: doc, folder, parts: parts.length, total })
  }
  const breaches = files.filter(f => ['archive', 'split', 'manual'].includes(f.verdict)).map(f => ({ ...f, action: f.verdict }))
  return { ok: linkErrors.length === 0, files, breaches, linkErrors, families }
}

// ── Split ───────────────────────────────────────────────────────────────────────────────────
// Deterministic split per keel-archive-guide "Splitting an oversize doc". Moves text verbatim.
// Plain doc NAME.md → its "## " sections go to <name>/NN-<slug>.md (adjacent sections merged
// while a part is under MIN_PART bytes); the parent keeps its H1 + intro and its "## Parts" table
// (created, or appended to — so a second run only moves what was added since). A part over budget
// keeps its first chunk and moves the rest to new parts (next free NN), added to the Parts table.
// Inbound links NAME.md#<heading> anywhere in the repo are repointed to the part holding it.
const MIN_PART = 2048
const slug = t => t.toLowerCase().replace(/[`*_[\]()]/g, '').replace(/[^\w\s-]/g, '').trim().replace(/\s+/g, '-')
function sections(text, level) {
  const mark = '#'.repeat(level) + ' '
  const out = [{ title: null, text: '' }]
  let fence = false
  for (const line of text.split(/(?<=\n)/)) {
    if (/^\s*(```|~~~)/.test(line)) fence = !fence
    if (!fence && line.startsWith(mark)) out.push({ title: line.slice(mark.length).trim(), text: '' })
    out[out.length - 1].text += line
  }
  return out
}
function group(secs, budget) {
  const groups = []
  for (const sec of secs) {
    const last = groups[groups.length - 1]
    if (last && Buffer.byteLength(last.text) < MIN_PART && Buffer.byteLength(last.text + sec.text) <= budget) {
      last.text += sec.text; last.titles.push(sec.title)
    } else groups.push({ titles: [sec.title], text: sec.text })
  }
  return groups
}
export function split(root, doc, budget) {
  const abs = join(root, doc), text = readFileSync(abs, 'utf8')
  const isPart = /^> Part of \[[^\]]+\]\(\.\.\/[^)]+\.md\)/m.test(text)
  const parentRel = isPart ? join(dirname(dirname(doc)), text.match(/^> Part of \[[^\]]+\]\(\.\.\/([^)#]+\.md)\)/m)[1]) : doc
  const folder = join(dirname(parentRel), kebab(parentRel))
  const parentBase = basename(parentRel)
  const parentText = isPart ? readFileSync(join(root, parentRel), 'utf8') : text
  const docTitle = (parentText.match(/^# (.+)$/m) || [, basename(parentRel, '.md')])[1].trim()
  // body sections: for a part, skip its own header (H1 + "Part of" line); for an index, its Parts table stays
  let lvl = 2, [head, ...secs] = sections(text, 2)
  const body = s => s.filter(x => x.title !== 'Parts')
  if (body(secs).length < (isPart ? 2 : 1)) { lvl = 3; [head, ...secs] = sections(text, 3) }
  const partsSec = lvl === 2 ? secs.find(x => x.title === 'Parts') : null
  secs = lvl === 2 ? body(secs) : secs
  if (secs.length < (isPart ? 2 : 1)) throw new Error(`${doc}: nothing to split — no "## " or "### " sections${hasParts(text) ? ' outside the Parts index (already split)' : ''}`)
  let groups = group(secs, budget)
  let keep = ''
  if (isPart) { keep = head.text + groups[0].text; groups = groups.slice(1) }
  if (!groups.length) throw new Error(`${doc}: one section only — split it by hand at a lower heading`)
  mkdirSync(join(root, folder), { recursive: true })
  let nn = Math.max(0, ...readdirSync(join(root, folder)).map(f => parseInt(f, 10) || 0)) + 1
  const made = [], moved = {}
  for (const g of groups) {
    const name = `${String(nn++).padStart(2, '0')}-${slug(g.titles[0]).slice(0, 40) || 'part'}.md`
    writeFileSync(join(root, folder, name),
      `# ${docTitle} — ${g.titles[0]}\n> Part of [${parentBase}](../${parentBase}) · all parts listed there.\n\n${g.text.replace(/^\n+/, '')}`)
    made.push({ name, covers: g.titles.join(', ') })
    for (const m of g.text.matchAll(/^#{2,6} (.+)$/gm)) moved[slug(m[1])] = join(folder, name)
  }
  const rows = made.map(m => `| [${m.name.replace(/\.md$/, '')}](${kebab(parentRel)}/${m.name}) | ${m.covers} |`).join('\n') + '\n'
  const addRows = pt => {
    const tbl = pt.match(/## Parts\n[\s\S]*?\n\|[^\n]*\|\n(?![|])/)
    return tbl ? pt.replace(tbl[0], tbl[0] + rows) : pt.trimEnd() + `\n\n## Parts\n\n| Part | Covers |\n|---|---|\n${rows}`
  }
  if (isPart) {
    writeFileSync(abs, keep)
    writeFileSync(join(root, parentRel), addRows(parentText))
  } else if (partsSec) {
    writeFileSync(abs, addRows(`${head.text.trimEnd()}\n\n${partsSec.text}`))
  } else {
    writeFileSync(abs, `${head.text.trimEnd()}\n\n## Parts\n\nSplit ${new Date().toISOString().slice(0, 10)} at ${Buffer.byteLength(text)} B > ${budget} B. Every part links back here.\n\n| Part | Covers |\n|---|---|\n${rows}`)
  }
  // repoint inbound anchored links (NAME.md#anchor) in every markdown file
  const walk = d => readdirSync(join(root, d), { withFileTypes: true }).flatMap(e =>
    e.name.startsWith('.') || e.name === 'node_modules' ? [] : e.isDirectory() ? walk(join(d, e.name)) : e.name.endsWith('.md') ? [join(d, e.name)] : [])
  let rewired = 0
  for (const f of walk('.')) {
    const src = readFileSync(join(root, f), 'utf8')
    const out = src.replace(/\]\(([^)\s#]*?)#([^)\s]+)\)/g, (all, target, anchor) => {
      if (!target || join(dirname(f), target) !== parentRel && join(dirname(f), target) !== doc) return all
      const to = moved[anchor]; if (!to) return all
      rewired++; return `](${relative(dirname(f), to)}#${anchor})`
    })
    if (out !== src) writeFileSync(join(root, f), out)
  }
  return { parent: parentRel, folder, parts: made.map(m => join(folder, m.name)), rewired }
}

if (process.argv.includes('--self-test')) {
  const fail = (what, o) => { console.log(`FAIL ${what} ` + JSON.stringify(o, null, 1)); process.exit(1) }
  const fixture = () => {
    const r = mkdtempSync(join(tmpdir(), 'keel-size-'))
    return [r, (f, s) => { mkdirSync(dirname(join(r, f)), { recursive: true }); writeFileSync(join(r, f), s) }]
  }
  const sec = (t, n) => `## ${t}\n\n${'Text about ' + t + '. '}${'lorem ipsum '.repeat(n)}\n\n### ${t} detail\n\nMore.\n\n`

  // 1. basic verdicts + link errors
  const [r, w] = fixture()
  w('.keel/meta.json', JSON.stringify({ budgets: { 'AGENTS.md': 50 }, defaultBudget: 100 }))
  w('AGENTS.md', 'x'.repeat(60))                                   // keystone breach → archive
  w('docs/PRD.md', '## A\n' + 'y'.repeat(120))                     // → split
  w('docs/DESIGN.md', '# D\n## Parts\n[a](design/01-a.md) [b](./design/02-b.md)\n')
  w('docs/design/01-a.md', '> Part of [DESIGN.md](../DESIGN.md)\n' + 'z'.repeat(40))
  w('docs/design/02-b.md', 'no back link')                        // back-link error
  w('docs/design/03-c.md', '[up](../DESIGN.md#parts)')             // not linked from parent
  w('docs/IMPLEMENTATION_PLAN.md', '## P\n' + 'p'.repeat(101))     // → archive (then split)
  const c = check(r)
  const v = Object.fromEntries(c.files.map(b => [b.file, b.verdict]))
  if (!(!c.ok && v['AGENTS.md'] === 'archive' && v['docs/PRD.md'] === 'split' && v['docs/IMPLEMENTATION_PLAN.md'] === 'archive' &&
    check(r, { afterArchive: true }).files.find(f => f.file === 'docs/IMPLEMENTATION_PLAN.md').verdict === 'split' &&
    v['docs/design/01-a.md'] === 'ok' && c.linkErrors.length === 2 && c.linkErrors.some(e => e.startsWith('docs/design/02-b.md: no link back')) &&
    c.linkErrors.some(e => e.startsWith('docs/design/03-c.md: not linked')) && c.families[0].parts === 3 &&
    c.files.filter(f => f.file === 'docs/DESIGN.md').length === 1)) fail('check', c)

  // 2. the cases a real 2.4.1 upgrade hit (cortextOS): every one gets a clear verdict, no false link errors
  const [q, wq] = fixture()
  const adrs = 60
  wq('.keel/meta.json', JSON.stringify({ defaultBudget: 4000, budgets: { 'AGENTS.md': 1000, 'docs/adr/README.md': 2000 },
    budgetExceptions: { 'docs/IMPLEMENTATION_PLAN.md': '55 open deferred rows; run /keel closeout' },
    waivers: { 'docs/SOC2_CONTROLS.md': { reason: 'auditor wants one file', reviewed: '2026-10-01' },
      'docs/BIG.md': { reason: 'ok up to 5000', reviewed: '2026-10-01', max: 5000 } } }))
  wq('AGENTS.md', 'k'.repeat(995))                                                  // tight keystone
  wq('docs/ADR.md', '# ADR.md → moved\n\nSee [index](./adr/README.md) and [legacy](adr/LEGACY_ADR.md).\n')
  for (let i = 1; i <= adrs; i++) wq(`docs/adr/ADR-${String(i).padStart(3, '0')}-x.md`, '# ADR\n' + 'a'.repeat(3000))
  wq('docs/adr/README.md', '# ADRs\n' + '| ADR | Title |\n'.repeat(1) + '| [ADR-001](ADR-001-x.md) | t |\n'.repeat(adrs * 3)) // > 2000, < 320×60
  wq('docs/adr/LEGACY_ADR.md', 'L'.repeat(50000))                                   // archive in the ADR folder
  wq('docs/PHASE_ARCHIVE.md', '# Archive\n' + sec('Phase 1', 9000))                  // archive: never split
  wq('docs/IMPLEMENTATION_PLAN.md', '# Plan\n' + sec('Deferred', 900))               // legacy exception → waived, review due
  wq('docs/SOC2_CONTROLS.md', '# SOC2\n' + sec('Controls', 900))                     // waived, reviewed
  wq('docs/BIG.md', '# Big\n' + sec('A', 300) + sec('B', 300))                       // waiver max exceeded → split
  wq('docs/GENERATED.md', '<!-- AUTO-GENERATED by scripts/gen.ts — do not edit -->\n' + sec('X', 900)) // → manual
  wq('docs/FLAT.md', 'no headings at all '.repeat(400))                              // → manual
  wq('docs/ONE.md', '# One\n## Only\n' + 'x'.repeat(5000))                            // one section, h3 none → split (1 section ok for plain doc)
  wq('docs/LINKS.md', '# Links\n## Parts\n\n[01]: /docs/links/01-a.md\n[a][01] and <docs/x> [b](</docs/links/02-b.md> "title")\n')
  wq('docs/links/01-a.md', '# L — A\n> Part of [LINKS.md](../LINKS.md)\nbody\n')
  wq('docs/links/02-b.md', '# L — B\nup: [parent][p]\n\n[p]: /docs/LINKS.md#parts\n')
  const k = check(q, { now: Date.parse('2026-10-31') })
  const kv = Object.fromEntries(k.files.map(f => [f.file, f]))
  const exp = { 'AGENTS.md': 'ok', 'docs/ADR.md': 'ok', 'docs/adr/README.md': 'ok', 'docs/PHASE_ARCHIVE.md': 'ok',
    'docs/IMPLEMENTATION_PLAN.md': 'waived', 'docs/SOC2_CONTROLS.md': 'waived', 'docs/BIG.md': 'split',
    'docs/GENERATED.md': 'manual', 'docs/FLAT.md': 'manual', 'docs/LINKS.md': 'ok', 'docs/links/01-a.md': 'ok' }
  const bad = Object.entries(exp).filter(([f, e]) => kv[f]?.verdict !== e)
  if (bad.length || !k.ok || k.families.length !== 1 || kv['docs/adr/LEGACY_ADR.md'] ||
    !/tight/.test(kv['AGENTS.md'].reason) || !/review due.*legacy/.test(kv['docs/IMPLEMENTATION_PLAN.md'].reason) ||
    !/reviewed 2026-10-01/.test(kv['docs/SOC2_CONTROLS.md'].reason) || !/320 B × 60/.test(kv['docs/adr/README.md'].reason) ||
    k.files.filter(f => f.file === 'docs/adr/README.md').length !== 1) fail('upgrade cases', { bad, k })
  // keystone over budget: guidance is "move out", never "compress"
  wq('AGENTS.md', 'k'.repeat(1100))
  const ks = check(q).files.find(f => f.file === 'AGENTS.md')
  if (ks.verdict !== 'archive' || !/move whole sections.*do not compress/.test(ks.reason)) fail('keystone', ks)
  // moved-out keystone sections are a linked family checked like any split
  wq('AGENTS.md', '# A\n## Parts\n| [01](docs/agents/01-delegation.md) | read when delegating |\n')
  wq('docs/agents/01-delegation.md', '# A — Delegation\n> Part of [AGENTS.md](../../AGENTS.md)\n')
  const kf = check(q)
  if (!kf.ok || !kf.families.some(f => f.parent === 'AGENTS.md' && f.parts === 1)) fail('keystone parts', kf)

  // 3. split fixture: append to an over-limit doc → split → index + parts, links both ways, no breach.
  const [r2, w2] = fixture()
  w2('.keel/meta.json', JSON.stringify({ defaultBudget: 4000 }))
  w2('AGENTS.md', 'See [components](docs/DESIGN.md#components) and [index](docs/DESIGN.md).\n')
  w2('docs/DESIGN.md', '# DESIGN — Demo\n\nIntro line.\n\n' + sec('Foundations', 200) + sec('Components', 200) +
    '```md\n## not a heading (in a fence)\n```\n\n')
  writeFileSync(join(r2, 'docs/DESIGN.md'), readFileSync(join(r2, 'docs/DESIGN.md'), 'utf8') + sec('Patterns', 200)) // the append
  const over = check(r2).breaches.map(b => b.file)
  const s1 = split(r2, 'docs/DESIGN.md', 4000)
  const c2 = check(r2)
  const idx = readFileSync(join(r2, 'docs/DESIGN.md'), 'utf8')
  const ag = readFileSync(join(r2, 'AGENTS.md'), 'utf8')
  // repeat run is a no-op (idempotent): an index with nothing new refuses, files unchanged
  let again = ''
  try { split(r2, 'docs/DESIGN.md', 4000) } catch (e) { again = e.message }
  // grow one part past the limit, split it again
  const p2 = join(r2, s1.parts[1])
  writeFileSync(p2, readFileSync(p2, 'utf8') + sec('States', 200))
  const s2 = split(r2, s1.parts[1], 4000)
  // someone writes a new section into the index: split moves only that, appends one Parts row
  writeFileSync(join(r2, 'docs/DESIGN.md'), readFileSync(join(r2, 'docs/DESIGN.md'), 'utf8') + '\n' + sec('Motion', 50))
  const s3 = split(r2, 'docs/DESIGN.md', 4000)
  const c3 = check(r2)
  const idx3 = readFileSync(join(r2, 'docs/DESIGN.md'), 'utf8')
  const ok2 = over.includes('docs/DESIGN.md') && s1.parts.length === 3 && c2.ok && c2.breaches.length === 0 &&
    /## Parts/.test(idx) && !/lorem/.test(idx) && c2.families[0].parts === 3 &&
    ag.includes('](docs/design/02-components.md#components)') && ag.includes('[index](docs/DESIGN.md)') &&
    readFileSync(join(r2, s1.parts[1]), 'utf8').includes('## not a heading (in a fence)') &&
    /already split/.test(again) && readFileSync(join(r2, 'docs/DESIGN.md'), 'utf8') !== '' &&
    s2.parts.length === 1 && s3.parts.length === 1 && c3.ok && c3.breaches.length === 0 && c3.families[0].parts === 5 &&
    idx3.includes('(design/' + basename(s2.parts[0]) + ')') && (idx3.match(/^## Parts/gm) || []).length === 1 && !/lorem/.test(idx3)
  if (!ok2) fail('split', { over, s1, s2, s3, again, c2, c3, idx3, ag })
  console.log('ok'); process.exit(0)
}

const si = process.argv.indexOf('--split')
if (si > 0) {
  const doc = process.argv[si + 1]
  const f = check('.', { afterArchive: true }).files.find(x => x.file === doc)
  const meta = (() => { try { return JSON.parse(readFileSync('.keel/meta.json', 'utf8')) } catch { return {} } })()
  const refuse = m => { console.error(`${doc}: not split — ${m}`); process.exit(2) }
  if (KEYSTONE.has(doc)) refuse('keystone: archive it, then move whole sections to a linked doc; never split')
  if (isArchive(doc, meta)) refuse('archive: append-only history, never split')
  if (f && ['waived', 'manual'].includes(f.verdict)) refuse(`${f.verdict}: ${f.reason}`)
  try {
    const r = split('.', doc, f ? f.budget : (meta.budgets || {})[doc] ?? meta.defaultBudget ?? 32768)
    console.log(`split ${doc}: ${r.parts.length} new part(s) in ${r.folder}/ — ${r.parts.join(', ')}; ${r.rewired} inbound link(s) repointed`)
  } catch (e) { refuse(e.message) }
}
const res = check('.', { afterArchive: process.argv.includes('--after-archive') })
if (process.argv.includes('--json')) console.log(JSON.stringify(res, null, 1))
else {
  const icon = { ok: '✅', waived: '🟡', archive: '📦', split: '✂️ ', manual: '✋' }
  for (const f of res.files) console.log(`${icon[f.verdict]} ${f.verdict.padEnd(7)} ${f.file} ${f.size}/${f.budget}B${f.part ? ` (part of ${f.part})` : ''}${f.reason ? ` — ${f.reason}` : ''}`)
  for (const fam of res.families) console.log(`   ${fam.parent} + ${fam.parts} parts in ${fam.folder}/ = ${fam.total}B total`)
  for (const e of res.linkErrors) console.log(`LINK ERROR ${e}`)
}
process.exit(res.ok ? 0 : 1)
